const b64 = window.__b64Parts.join('');
const bin = atob(b64);
const bytes = new Uint8Array(bin.length);
for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
const blob = new Blob([bytes], {type: 'image/png'});
const file = new File([blob], '04-profile.png', {type: 'image/png'});
const input = document.querySelector('input[type=file][accept*="png"]');
if (!input) { 'NO_INPUT'; } else {
  const dt = new DataTransfer();
  dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event('change', {bubbles: true}));
  input.dispatchEvent(new Event('input', {bubbles: true}));
  JSON.stringify({ok:true, files:input.files.length, size:input.files[0].size});
}
